from __future__ import annotations

import json
import os
from pathlib import Path
import sys
import warnings


TASK_ROOT = Path(__file__).resolve().parent
SOURCE_ROOT = TASK_ROOT / "source"
FIXTURE_PATH = TASK_ROOT / "fixtures" / "workbench.json"
REPORT_PATH = TASK_ROOT / "outputs" / "public_reproduction_report.json"


def write_report(payload: dict[str, object], exit_code: int) -> int:
    REPORT_PATH.parent.mkdir(exist_ok=True)
    text = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    REPORT_PATH.write_text(text, encoding="utf-8")
    print(text, end="")
    return exit_code


def main() -> int:
    try:
        os.environ.setdefault("MPLBACKEND", "Agg")
        sys.path.insert(0, str(SOURCE_ROOT))
        sys.path.insert(0, str(TASK_ROOT))
        from workflow.workbench import run

        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            report = run(FIXTURE_PATH)
    except Exception as exc:  # noqa: BLE001
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
            },
            2,
        )
    return write_report(report, 0 if report["status"] == "workflow_completed" else 2)


if __name__ == "__main__":
    raise SystemExit(main())
from __future__ import annotations

from pathlib import Path
import json
import sys

import numpy as np


def _model_from_case(case: dict, fixture: dict):
    # Import through the task's source path so the workbench is self-contained.
    from Pynite import FEModel3D

    model = FEModel3D()
    material = fixture["material"]
    section = fixture["section"]
    model.add_material(
        material["name"], material["E"], material["G"], material["nu"], material["rho"]
    )
    model.add_section(
        section["name"], section["A"], section["Iy"], section["Iz"], section["J"]
    )
    for name, x, y, z in case["nodes"]:
        model.add_node(name, x, y, z)
    for name, i, j in case["members"]:
        model.add_member(name, i, j, material["name"], section["name"])

    for node in case.get("fixed_nodes", []):
        model.def_support(node, True, True, True, True, True, True)
    for node in case.get("pinned_nodes", []):
        # The end supports leave model-axis rotation free, as in a pin/roller
        # idealization; the member continuity supplies the remaining restraint.
        model.def_support(node, True, True, True, True, True, False)

    load = case["load"]
    if len(load) == 3:
        model.add_node_load(load[0], load[1], load[2])
    else:
        model.add_member_dist_load(load[0], load[1], load[2], load[3])
    if case.get("release"):
        member, release = case["release"]
        model.def_releases(member, **{release: True})
    return model


def _scalar(value) -> float:
    arr = np.asarray(value, dtype=float)
    return float(arr.reshape(-1)[0])


def _observe(model) -> dict[str, object]:
    displacements: list[float] = []
    reactions: list[float] = []
    for node in model.nodes.values():
        for field in (node.DX, node.DY, node.DZ, node.RX, node.RY, node.RZ):
            if "Combo 1" in field:
                displacements.append(_scalar(field["Combo 1"]))
        for field in (node.RxnFX, node.RxnFY, node.RxnFZ, node.RxnMX, node.RxnMY, node.RxnMZ):
            if "Combo 1" in field:
                reactions.append(_scalar(field["Combo 1"]))
    disp = np.asarray(displacements, dtype=float)
    rxn = np.asarray(reactions, dtype=float)
    max_disp = float(np.max(np.abs(disp))) if disp.size and np.isfinite(disp).all() else None
    reaction_l1 = float(np.sum(np.abs(rxn))) if rxn.size and np.isfinite(rxn).all() else None
    return {
        "finite_values": bool(np.isfinite(disp).all() and np.isfinite(rxn).all()),
        "max_abs_displacement": max_disp,
        "reaction_l1": reaction_l1,
        "displacement_count": int(disp.size),
    }


def run_case(case: dict, fixture: dict) -> list[dict[str, object]]:
    reports = []
    for path_name, method in (("general", "analyze"), ("linear", "analyze_linear")):
        for sparse in (True, False):
            model = _model_from_case(case, fixture)
            item: dict[str, object] = {
                "case": case["name"],
                "analysis_path": path_name,
                "solver": "sparse" if sparse else "dense",
            }
            try:
                getattr(model, method)(sparse=sparse, check_stability=True, check_statics=False)
            except Exception as exc:  # a bounded scientific observation
                item["status"] = "analysis_exception"
                item["error_type"] = type(exc).__name__
            else:
                # Observation extraction is part of the runner contract.  If it
                # fails, let the top-level runner report infrastructure failure
                # instead of misclassifying it as a solver result.
                item["status"] = "completed"
                item["observation"] = _observe(model)
            reports.append(item)
    return reports


def run(fixture_path: Path) -> dict[str, object]:
    fixture = json.loads(fixture_path.read_text(encoding="utf-8"))
    reports = [item for case in fixture["cases"] for item in run_case(case, fixture)]
    has_finite_control = any(
        item.get("status") == "completed"
        and item.get("observation", {}).get("finite_values") is True
        for item in reports
    )
    return {
        "schema_version": "1.0",
        "status": "workflow_completed" if has_finite_control else "runner_failure",
        "observations": reports,
    }

